-- Results generated by Spring Batch jobs

CREATE TABLE IF NOT EXISTS recommender_trending_post (
    id UUID PRIMARY KEY,
    post_id UUID NOT NULL,
    author_id UUID NOT NULL,
    content_type VARCHAR(20) NOT NULL,
    caption TEXT,
    tags TEXT,
    score DOUBLE PRECISION NOT NULL,
    likes_count BIGINT NOT NULL DEFAULT 0,
    rank INTEGER NOT NULL DEFAULT 0,
    calculated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_recommender_trending_score_time
    ON recommender_trending_post (calculated_at DESC, score DESC);
CREATE INDEX IF NOT EXISTS idx_recommender_trending_post_id
    ON recommender_trending_post (post_id);

CREATE TABLE IF NOT EXISTS recommender_user_recommendation (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL,
    recommended_user_id UUID NOT NULL,
    score DOUBLE PRECISION NOT NULL,
    mutual_friends_count BIGINT NOT NULL DEFAULT 0,
    reason VARCHAR(255),
    calculated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_recommender_user_rec_user_score
    ON recommender_user_recommendation (user_id, score DESC);
CREATE INDEX IF NOT EXISTS idx_recommender_user_rec_pair
    ON recommender_user_recommendation (user_id, recommended_user_id);
